/**
 * API handlers for user management.
 */
const db = require("../../store/lib/db");
const { validateUser } = require("./validate");

function handleCreate(body) {
  const errors = validateUser(body);
  if (errors.length > 0) {
    return { status: 400, body: { error: "Validation failed", details: errors } };
  }

  // Check for duplicate email before creating
  const existing = db.findByEmail(body.email);
  if (existing) {
    return { status: 409, body: { error: "A user with this email already exists" } };
  }

  try {
    const user = db.createUser(body.name, body.email);
    return { status: 201, body: user };
  } catch (err) {
    return { status: 500, body: { error: "Internal server error" } };
  }
}

function handleGet(id) {
  const user = db.getUser(id);
  if (!user) {
    return { status: 404, body: { error: "User not found" } };
  }
  return { status: 200, body: user };
}

function handleList() {
  return { status: 200, body: db.listUsers() };
}

function handleDelete(id) {
  if (!db.getUser(id)) {
    return { status: 404, body: { error: "User not found" } };
  }
  db.deleteUser(id);
  return { status: 204, body: null };
}

module.exports = { handleCreate, handleGet, handleList, handleDelete };

/**
 * In-memory user store.
 */
const users = new Map();
let nextId = 1;

function createUser(name, email) {
  // Bug: doesn't check for duplicate emails before inserting
  const id = nextId++;
  const user = { id, name, email, createdAt: new Date().toISOString() };
  users.set(id, user);
  return user;
}

function getUser(id) {
  return users.get(id) || null;
}

function listUsers() {
  return Array.from(users.values());
}

function findByEmail(email) {
  for (const user of users.values()) {
    if (user.email === email) return user;
  }
  return null;
}

function deleteUser(id) {
  return users.delete(id);
}

function clear() {
  users.clear();
  nextId = 1;
}

module.exports = { createUser, getUser, listUsers, findByEmail, deleteUser, clear };
